const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const plumePoint = ee.Geometry.Point([-136.275745, 69.264212]);
  const oceanPoint = ee.Geometry.Point([-137.786365, 69.803894]);

  // Buffer of 500m to get region averages (avoid single noisy pixel)
  const plumeRegion = plumePoint.buffer(500);
  const oceanRegion = oceanPoint.buffer(500);

  const targetDate = '2017-07-19';
  const startDate = ee.Date(targetDate).advance(-1, 'day');
  const endDate = ee.Date(targetDate).advance(1, 'day');

  // 2. Data Acquisition - Try Sentinel-2 (best for water color)
  let s2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(startDate, endDate)
    .filterBounds(plumeRegion.union(oceanRegion))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let imgCount = s2.size().getInfo();
  console.log(`Sentinel-2 images (${startDate.format('YYYY-MM-dd').getInfo()} to ${endDate.format('YYYY-MM-dd').getInfo()}): ${imgCount}`);

  let collection = s2;
  let band = 'B3'; // Green band for turbidity/milkiness
  let scale = 30; // Sentinel-2 native resolution

  // Fallback to Landsat 8 if no Sentinel-2
  if (imgCount === 0) {
    console.log('No Sentinel-2, trying Landsat 8...');
    const landsatStart = ee.Date(targetDate).advance(-7, 'day');
    const landsatEnd = ee.Date(targetDate).advance(7, 'day');

    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(landsatStart, landsatEnd)
      .filterBounds(plumeRegion.union(oceanRegion))
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    imgCount = collection.size().getInfo();
    console.log(`Landsat 8 images (7-day window): ${imgCount}`);
    band = 'SR_B3'; // Green band for Landsat 8
    scale = 30;

    if (imgCount === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Select the image closest to target date
  const image = ee.Image(collection.sort('system:time_start').first());

  // Cloud masking for Sentinel-2 (using QA60)
  let maskedImage = image;
  if (collection.get('id').getInfo().includes('COPERNICUS/S2')) {
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const qa = image.select('QA60');
    maskedImage = image.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0))
                       .updateMask(qa.bitwiseAnd(cirrusBitMask).eq(0));
  } else {
    // Landsat 8 cloud masking using QA_PIXEL
    const cloudMask = image.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0)
                          .and(image.select('QA_PIXEL').bitwiseAnd(1 << 4).eq(0));
    maskedImage = image.updateMask(cloudMask);
  }

  // 3. Check valid pixels in both regions
  const plumeCount = maskedImage.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: plumeRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get(band).getInfo();

  const oceanCount = maskedImage.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: oceanRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get(band).getInfo();

  console.log(`Plume valid pixels: ${plumeCount}, Ocean valid pixels: ${oceanCount}`);

  if (plumeCount === 0 || oceanCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate mean reflectance in green band
  const plumeMean = maskedImage.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: plumeRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get(band).getInfo();

  const oceanMean = maskedImage.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: oceanRegion,
    scale: scale,
    maxPixels: 1e9,
  }).get(band).getInfo();

  console.log(`Plume ${band} reflectance: ${plumeMean ? plumeMean.toFixed(4) : 'null'}`);
  console.log(`Ocean ${band} reflectance: ${oceanMean ? oceanMean.toFixed(4) : 'null'}`);

  // 5. Validation & Final Answer
  if (plumeMean === null || oceanMean === null || 
      isNaN(plumeMean) || isNaN(oceanMean) ||
      plumeMean < 0 || plumeMean > 1 || 
      oceanMean < 0 || oceanMean > 1) {
    console.log('<answer>C3</answer>');
  } else if (plumeMean > oceanMean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
